function reportTabs(sub) { return tabs([['overview', L('สถิติโดยรวม', 'Statistics'), 'reports'], ['insights', L('วิเคราะห์เชิงลึก', 'Insights'), 'breakdown'], ['compare', L('เปรียบเทียบ', 'Compare'), 'compare'], ['psychology', L('วินัย & จิตวิทยา', 'Psychology'), 'brain'], ['calendar', L('ปฏิทิน', 'Calendar'), 'calendar'], ['simulation', L('จำลองผล', 'Simulation'), 'simulation']], sub, 'report-tab'); }
function reportsView(sub, sub2) {
  const rows = filtered(), titles = { overview: L('สถิติโดยรวม', 'Statistics'), calendar: L('ปฏิทิน', 'Calendar'), insights: L('วิเคราะห์เชิงลึก', 'Insights'), cross: L('ตารางไขว้', 'Cross matrix'), compare: L('เปรียบเทียบ', 'Compare'), psychology: L('วินัย & จิตวิทยา', 'Discipline & psychology'), simulation: L('จำลองผล', 'Simulation') };
  const subs = { overview: L('ทุกตัวชี้วัดที่สำคัญของผลการเทรด', 'Every key performance metric'), calendar: L('ภาพรวมผลลัพธ์รายวันตลอดทั้งปี', 'Daily results across the year'), insights: L('หาว่า edge ของคุณอยู่ตรงไหน — และรั่วตรงไหน', 'Find where your edge lives — and where it leaks'), cross: L('เทียบสองมิติพร้อมกัน เช่น สินทรัพย์ × Session', 'Two dimensions at once'), compare: L('เปรียบเทียบสองกลุ่มเทรด และวิเคราะห์ไขว้ 2 มิติ (Cross Analysis)', 'Two trade groups side by side, plus two-dimension Cross Analysis'), psychology: L('อารมณ์ ความผิดพลาด และวินัยส่งผลต่อผลลัพธ์อย่างไร', 'How emotions, mistakes and discipline affect results'), simulation: L('จำลองอนาคตด้วย Monte Carlo และทดสอบสถานการณ์ What-if', 'Monte Carlo simulation and what-if scenarios') };
  if (sub === 'breakdown') sub = 'insights'; if (sub === 'risk') sub = 'simulation';
  if (sub === 'cross') sub = 'compare';
  if (sub === 'drill') { sub = 'insights'; sub2 = insTabOf(ui.dimension); }
  let body = '';
  switch (sub) { case 'calendar': body = yearCalendar(rows); break; case 'insights': body = insightsView(rows, sub2); break; case 'compare': body = compareView(); break; case 'psychology': body = psychologyView(rows); break; case 'simulation': body = riskLabView(rows); break; default: body = overviewReport(rows); }
  return pageHead(titles[sub] || titles.overview, subs[sub] || '', `${btn(icon('download') + L(' ส่งออกรายงาน', ' Export report'), 'export-report')}${btn(icon('external') + L(' พิมพ์ / PDF', ' Print / PDF'), 'print')}`) + reportTabs(sub) + (sub === 'compare' ? '' : scopeLine(rows)) + body;
}
function statRows(items) { return items.map(([l, v, cls = '', tip = '']) => `<div class="srow"><span ${tip ? `data-tip="${esc(tip)}"` : ''}>${l}${tip ? ' ' + icon('info', 'tiny') : ''}</span><strong class="${cls}">${v}</strong></div>`).join(''); }
