    + `<div class="grid g2 mb16">${panel(L('ผลลัพธ์ตามอารมณ์', 'Results by emotion'), chartBox({ type: 'hbar', data: emo.map(g => ({ label: g.label, y: g.s.expectancy ?? 0, sub: `${g.s.n} ${L('เทรด', 'trades')} · ${L('อัตราชนะ', 'Win rate')} ${fmt(g.s.wr, 0)}% · ${L('รวม', 'total')} ${unitFmt(g.s.total)}` })), valueFmt: v => unitFmt(v, u), empty: L('บันทึกอารมณ์ในแต่ละเทรดเพื่อดูผล', 'Record emotions on trades to see this') }, Math.max(180, emo.length * 32)), '', '', L('ค่าคาดหวังต่อเทรด', 'Expectancy per trade'))}${panel(L('ต้นทุนแยกตามความผิดพลาด', 'Cost by mistake'), mistOnly.length ? `<div class="tablewrap"><table><thead><tr><th>${L('ความผิดพลาด', 'Mistake')}</th><th class="num">${L('ครั้ง', 'Count')}</th><th class="num">${L('ผลรวม', 'Impact')}</th><th class="num">${L('เฉลี่ย', 'Average')}</th><th style="width:30%"></th></tr></thead><tbody>${mistOnly.sort((a, b) => (a.s.total ?? 0) - (b.s.total ?? 0)).map(g => { const mx = Math.max(EPS, ...mistOnly.map(x => Math.abs(x.s.total || 0))); return `<tr class="click" data-action="drill" data-dim="mistake" data-key="${esc(g.key)}"><td>${esc(g.label)}</td><td class="num">${g.s.n}</td><td class="num"><strong class="${tone(g.s.total)}">${unitFmt(g.s.total)}</strong></td><td class="num">${unitFmt(g.s.expectancy)}</td><td>${progress(Math.abs(g.s.total || 0) / mx * 100, (g.s.total || 0) < 0 ? 'neg' : 'pos')}</td></tr>`; }).join('')}</tbody></table></div>` : empty(L('ยังไม่มีแท็กความผิดพลาด', 'No mistake tags yet'), L('ติดแท็กหมวด "ความผิดพลาด" เพื่อวัดต้นทุนของแต่ละพฤติกรรม', 'Tag mistakes to measure their cost')), '', 'flush')}</div>`
