    + panel(L('ไทม์ไลน์วินัย (60 วันเทรดล่าสุด)', 'Discipline timeline (last 60 trading days)'), `<div class="row wrap gap4">${disc.map(({ d, x }) => `<span data-action="open-day" data-day="${d}" data-tip="${esc(fmtDate(d) + '\n' + (x.issues.length ? x.issues.join(' · ') : L('ไม่ผิดกฎ', 'Clean')))}" style="width:18px;height:28px;border-radius:4px;cursor:pointer;background:${x.issues.length ? (x.issues.length > 1 ? 'var(--neg)' : 'var(--warn)') : 'var(--pos)'};opacity:${x.issues.length ? 1 : .75}"></span>`).join('') || '<span class="dim">—</span>'}</div><div class="legend mt16"><span><i style="background:var(--pos)"></i>${L('ไม่ผิดกฎ', 'Clean')}</span><span><i style="background:var(--warn)"></i>${L('ผิด 1 ข้อ', '1 issue')}</span><span><i style="background:var(--neg)"></i>${L('ผิดหลายข้อ', '2+ issues')}</span></div>`, btn(icon('settings') + L(' ตั้งกฎ', ' Rules'), 'nav', { 'data-route': 'settings/rules' }, 'sm'))
