  const out = res ? `<div class="mc-stats mt16">${kpi(L('มูลค่าพอร์ตค่ากลาง', 'Median final'), money(res.medianFinal), `${fmt((res.medianFinal / start - 1) * 100, 1, true)}%`)}${kpi(L('กรณีแย่ (P5)', 'Bad case (P5)'), `<span class="${tone(res.p5Final - start)}">${money(res.p5Final)}</span>`)}${kpi(L('กรณีดี (P95)', 'Good case (P95)'), `<span class="pos">${money(res.p95Final)}</span>`)}${kpi(L('โอกาสมีกำไร', 'Probability of profit'), fmt(res.profitPct, 1) + '%')}${kpi(L('Max drawdown ค่ากลาง', 'Median max drawdown'), `<span class="neg">${fmt(res.medianDD, 1)}%</span>`, `P95 ${fmt(res.p95DD, 1)}%`)}${kpi(L('ความเสี่ยงล้างพอร์ต', 'Risk of ruin'), `<span class="${res.ruinPct > 5 ? 'neg' : res.ruinPct > 1 ? 'warn' : 'pos'}">${fmt(res.ruinPct, 1)}%</span>`, L(`DD ≥ ${mc.ruin}%`, `DD ≥ ${mc.ruin}%`))}</div><div class="mt16">${chartBox({ type: 'band', bands: res.bands, sample: res.sample, start }, 320)}</div>` : `<div class="mt16">${empty(L('ต้องมีอย่างน้อย 5 เทรดที่มีค่า ' + (mc.basis === 'R' ? 'R (มีระดับ Stop)' : 'P&L'), 'Need at least 5 trades with ' + mc.basis), '', '', 'dice')}</div>`;
  // what-if
  const wi = ui.whatIf || {}, base = closed;
  let alt = base.slice();
  if (wi.noMistakes) alt = alt.filter(t => !(t.tags || []).some(isMistakeTag));
