  const bTot = bs.at(-1)?.y ?? 0, aTot = as.at(-1)?.y ?? 0, bst = stats(base), ast = (() => { const st = stats(alt); return st; })();
  const toggles = [['noMistakes', L('ตัดเทรดที่มีความผิดพลาดออก', 'Remove trades tagged as mistakes'), L('ถ้าคุณมีวินัย 100%', 'If you were 100% disciplined')], ['capLoss', L('จำกัดขาดทุนไม่เกิน −1R', 'Cap every loss at −1R'), L('ถ้าไม่เคยเลื่อนระดับ Stop หรือปล่อยให้ขาดทุนเกินแผน', 'If you never let a loss exceed plan')], ['bestPb', L('เทรดเฉพาะ Strategy ที่ดีที่สุด', 'Trade only your best strategy'), L('โฟกัสกับ edge ที่แข็งแรงที่สุด', 'Focus on your strongest edge')], ['dropWorstSession', L('ไม่เทรดใน Session ที่แย่ที่สุด', 'Skip your worst session'), L('ตัด session ที่ขาดทุนสุทธิ', 'If it is net negative')], ['dropWorstDay', L('ไม่เทรดในวันที่แย่ที่สุดของสัปดาห์', 'Skip your worst weekday'), ''], ['maxTrades', L(`จำกัดไม่เกิน ${state.settings.rules?.maxTradesPerDay || 3} เทรด/วัน`, `Max ${state.settings.rules?.maxTradesPerDay || 3} trades/day`), L('ตัดเทรดส่วนเกินของแต่ละวัน', 'Drop overtrading')]];
  const whatIf = `<div class="grid g-12"><div class="toggles">${toggles.map(([k, l, d]) => `<div class="toggle-row"><div><strong>${l}</strong>${d ? `<small>${d}</small>` : ''}</div>${toggle('wi_' + k, !!wi[k], 'what-if', `data-k="${k}"`)}</div>`).join('')}</div><div><div class="kpis mb16">${kpi(L('ผลจริง', 'Actual'), `<span class="${tone(bTot)}">${unitFmt(bTot)}</span>`, `${bst.n} ${L('เทรด', 'trades')} · ${L('อัตราชนะ', 'Win rate')} ${fmt(bst.wr, 0)}%`)}${kpi(L('ผลจำลอง', 'What-if'), `<span class="${tone(aTot)}">${unitFmt(aTot)}</span>`, `${alt.length} ${L('เทรด', 'trades')} · ${L('อัตราชนะ', 'Win rate')} ${fmt(ast.wr, 0)}%`)}${kpi(L('ส่วนต่าง', 'Difference'), `<span class="${tone(aTot - bTot)}">${unitFmt(aTot - bTot)}</span>`, finite(bTot) && Math.abs(bTot) > EPS ? fmt((aTot - bTot) / Math.abs(bTot) * 100, 0, true) + '%' : '')}</div>${chartBox({ type: 'line', series: [{ name: L('ผลจริง', 'Actual'), data: bs, color: 'var(--dim)' }, { name: 'What-if', data: asAligned, color: 'var(--accent)' }], unit: ui.unit }, 260)}</div></div>`;
  // risk of ruin table by risk %
  const ruinRows = rs.length >= 5 ? [.25, .5, 1, 1.5, 2, 3].map(rp => { const r2 = monteCarlo(rs, { runs: 300, trades: mc.trades, riskPct: rp, start: 10000, ruin: mc.ruin, basis: 'R', seed: 11 }); return `<tr class="${Math.abs(rp - mc.riskPct) < EPS ? 'sel' : ''}"><td>${fmt(rp, 2)}%</td><td class="num">${fmt((r2.medianFinal / 10000 - 1) * 100, 1, true)}%</td><td class="num">${fmt((r2.p5Final / 10000 - 1) * 100, 1, true)}%</td><td class="num neg">${fmt(r2.medianDD, 1)}%</td><td class="num neg">${fmt(r2.p95DD, 1)}%</td><td class="num"><strong class="${r2.ruinPct > 5 ? 'neg' : r2.ruinPct > 1 ? 'warn' : 'pos'}">${fmt(r2.ruinPct, 1)}%</strong></td></tr>`; }).join('') : '';
  return panel(icon('dice') + ' Monte Carlo', ctrl + out, btn(icon('refresh') + L(' จำลองใหม่', ' Re-run'), 'mc-run', {}, 'sm'), 'mb16', L('สุ่มเรียงลำดับผลเทรดในอดีตใหม่หลายร้อยครั้ง เพื่อดูช่วงผลลัพธ์ที่เป็นไปได้ — ไม่ใช่การพยากรณ์', 'Resamples your past results to show a range of plausible outcomes — not a forecast'))
